Add three more validators in `validators_later.py`, in the same form as the ones in `validators.py`:

- V7 (`entries`): every warehouse's capacity was respected across runs. Each entry: `{"wh": str, "capacity": int, "max_units": int}`.
- V8 (`entries`): all expiries were notified. Each entry: `{"expired": [[sku, wh, qty], ...], "notified": [[sku, wh, qty], ...]}`.
- V9 (`entries`): every supplier's reliability stayed in range. Each entry: `{"supplier": str, "reliability": int}`.

## Repository files

`CONTRIBUTING.md`:

```
# Contributing

- Python 3.11, standard library only.
- Keep functions small and name them after what they check or do.
- Every change comes with tests.
- `vendor/` is read-only; report problems with `ask_owner`.
- Checks: an empty result never passes a check.
```

`validators.py`:

```
"""Validators over depot harness outputs.

Each validator vN(items) returns (passed, measured).
An empty input never passes.
"""

from typing import Any

# Notification types named in the spec (C17, C13, C14, C22, C20).
REQUIRED_NOTIFICATION_TYPES = frozenset({
    "SUPPLIER_SUSPENDED",
    "EXPIRY",
    "REORDER",
    "AUDIT_MISMATCH",
    "OVERDRAWN",
})


def _is_int(x: Any) -> bool:
    return isinstance(x, int) and not isinstance(x, bool)


def v1(items):
    """V1 (rows): every report row has value_cents == units * unit_cost."""
    if not items:
        return False, {"checked": 0, "bad_rows": []}

    bad = []
    for idx, row in enumerate(items):
        try:
            units = row["units"]
            value = row["value_cents"]
            cost = row["unit_cost"]
            ok = (
                _is_int(units)
                and _is_int(value)
                and _is_int(cost)
                and value == units * cost
            )
        except (KeyError, TypeError):
            ok = False
        if not ok:
            bad.append(idx)

    measured = {"checked": len(items), "bad_rows": bad}
    return not bad, measured


def v2(items):
    """V2 (runs): every required notification type was seen across all runs."""
    if not items:
        return False, {"seen": [], "missing": sorted(REQUIRED_NOTIFICATION_TYPES)}

    seen = set()
    for run in items:
        for note in run:
            if isinstance(note, tuple) and note:
                seen.add(note[0])
            elif isinstance(note, list) and note:
                seen.add(note[0])

    missing = sorted(REQUIRED_NOTIFICATION_TYPES - seen)
    measured = {"seen": sorted(seen), "missing": missing}
    return not missing, measured


def v3(items):
    """V3 (pairs): two runs with the same seed are identical."""
    if not items:
        return False, {"checked": 0, "mismatched_seeds": []}

    mismatched = []
    for pair in items:
        try:
            same = pair["a"] == pair["b"]
            seed = pair["seed"]
        except (KeyError, TypeError):
            mismatched.append(None)
            continue
        if not same:
            mismatched.append(seed)

    measured = {"checked": len(items), "mismatched_seeds": mismatched}
    return not mismatched, measured


def v4(items):
    """V4 (days): storage cost stayed within budget on every day."""
    if not items:
        return False, {"checked": 0, "over_budget_days": []}

    over = []
    for entry in items:
        try:
            cost = entry["storage_cost_cents"]
            budget = entry["budget_cents"]
            day = entry["day"]
            ok = _is_int(cost) and _is_int(budget) and cost <= budget
        except (KeyError, TypeError):
            ok = False
            day = None
        if not ok:
            over.append(day)

    measured = {"checked": len(items), "over_budget_days": over}
    return not over, measured


def v5(items):
    """V5 (clauses): every clause has at least one test."""
    if not items:
        return False, {"checked": 0, "untested_clauses": []}

    untested = []
    for entry in items:
        try:
            tests = entry["tests"]
            clause_id = entry["clause_id"]
            ok = isinstance(tests, (list, tuple)) and len(tests) >= 1
        except (KeyError, TypeError):
            ok = False
            clause_id = None
        if not ok:
            untested.append(clause_id)

    measured = {"checked": len(items), "untested_clauses": untested}
    return not untested, measured


def v6(items):
    """V6 (pairs): two implementations agree on every compared pair."""
    if not items:
        return False, {"checked": 0, "disagreeing_keys": []}

    disagreeing = []
    for pair in items:
        try:
            same = pair["a"] == pair["b"]
            key = pair["key"]
        except (KeyError, TypeError):
            disagreeing.append(None)
            continue
        if not same:
            disagreeing.append(key)

    measured = {"checked": len(items), "disagreeing_keys": disagreeing}
    return not disagreeing, measured
