"""Further validators over depot harness outputs.

Same conventions as validators.py: each vN(items) returns (passed, measured).
An empty input never passes.
"""

from collections import Counter
from typing import Any

from validators import _is_int

# Assumed reliability scale (the spec for V9 does not state a range).
RELIABILITY_MIN = 0
RELIABILITY_MAX = 100


def _expiry_counter(rows: Any):
    """Turn [[sku, wh, qty], ...] into a Counter of tuples, or None if malformed."""
    if not isinstance(rows, (list, tuple)):
        return None
    out = Counter()
    for row in rows:
        if not isinstance(row, (list, tuple)) or len(row) != 3:
            return None
        sku, wh, qty = row
        if not (isinstance(sku, str) and isinstance(wh, str) and _is_int(qty)):
            return None
        out[(sku, wh, qty)] += 1
    return out


def _unnotified_expiries(entry: Any):
    """Return expired rows with no matching notification (as lists), or None if malformed."""
    try:
        expired = entry["expired"]
        notified = entry["notified"]
    except (KeyError, TypeError):
        return None
    expired_c = _expiry_counter(expired)
    notified_c = _expiry_counter(notified)
    if expired_c is None or notified_c is None:
        return None
    gap = expired_c - notified_c
    return [list(t) for t in gap.elements()]


def v7(items):
    """V7 (runs): every warehouse's max units stayed within its capacity."""
    if not items:
        return False, {"checked": 0, "over_capacity_whs": []}

    over = []
    for entry in items:
        try:
            wh = entry["wh"]
            capacity = entry["capacity"]
            max_units = entry["max_units"]
            ok = (
                isinstance(wh, str)
                and _is_int(capacity)
                and _is_int(max_units)
                and max_units <= capacity
            )
        except (KeyError, TypeError):
            ok = False
            wh = None
        if not ok:
            over.append(wh)

    measured = {"checked": len(items), "over_capacity_whs": over}
    return not over, measured


def v8(items):
    """V8 (runs): every expired row was matched by a notification."""
    if not items:
        return False, {"checked": 0, "malformed": [], "unnotified": []}

    malformed = []
    unnotified = []
    for idx, entry in enumerate(items):
        missing = _unnotified_expiries(entry)
        if missing is None:
            malformed.append(idx)
        else:
            unnotified.extend(missing)

    measured = {
        "checked": len(items),
        "malformed": malformed,
        "unnotified": unnotified,
    }
    return not malformed and not unnotified, measured


def v9(items):
    """V9 (suppliers): every supplier's reliability is within range."""
    if not items:
        return False, {"checked": 0, "out_of_range": []}

    bad = []
    for entry in items:
        try:
            supplier = entry["supplier"]
            reliability = entry["reliability"]
            ok = (
                isinstance(supplier, str)
                and _is_int(reliability)
                and RELIABILITY_MIN <= reliability <= RELIABILITY_MAX
            )
        except (KeyError, TypeError):
            ok = False
            supplier = None
        if not ok:
            bad.append(supplier)

    measured = {"checked": len(items), "out_of_range": bad}
    return not bad, measured
